"""IR5A findings, part 1 (critical). Evidence: universe ids (quote reused mechanically) or (source_file, start, end) cuts."""
S = "sources/"
FINDINGS = [
 dict(id="R5A-01", kind="partial", severity="critical", rule_ids=["NY:ADJ-provide-written-dispatch", "NY:STT-305(3)", "NY:GOL-7-108(1-a)(e)-forfeiture"],
  step="S6 statement delivery / S8 forfeiture", universe=["U5A-203", "U5A-007"],
  finding="The rules let the landlord 'provide' the 14-day itemized statement by email or text with no consent condition, and read ESRA (STT 305) as making any electronic record equal to paper. Neither the rule files nor 4A contain the federal E-SIGN consumer-consent rule. GOL 7-108(1-a)(e) requires information (an itemized statement) to be provided to a consumer in writing; under 15 USC 7001(c) an electronic record satisfies that only after the tenant's affirmative E-SIGN consent. ESRA cannot displace 7001(c): it is not UETA, and its equivalence rule is inconsistent with 7001(c) (7002(a)). E-SIGN reaches residential rental agreements (7003(b)(2)(B) names them). A statement e-mailed without consent is not 'provided' in writing, so a landlord relying on it alone within 14 days forfeits.",
  correct_rule="If the itemized statement (GOL 7-108(1-a)(e)) or any other information the chain's statutes require be given to the tenant in writing is sent electronically, it counts as provided only if before sending the tenant (a) received the 7001(c)(1)(B) disclosures (right to paper, right to withdraw, scope, how to get paper), (b) affirmatively consented electronically in a way that reasonably shows it can access the format, and (c) has not withdrawn consent. Otherwise the statement must go on paper (mail or hand delivery) within the 14 days; email may be sent in addition. The refund payment itself is not 'information' and may be made by any means directed to the tenant. Notices of default, eviction or the right to cure under a residential rental agreement (e.g., the RPAPL 711(2) 14-day rent demand) are outside E-SIGN (7003(b)(2)(B)) and must be on paper. Federal law prevails over STT 305 to the extent inconsistent (Supremacy; 7002(a)).",
  extra=[(S+"REVIEW5A_US_15USC_7001_ESIGN.txt", "(2) require any person to agree to use or accept electronic records or electronic signatures", "with respect to a record other than a contract to which it is a party."),
         (S+"REVIEW5A_US_15USC_7003_ESIGN.txt", "(B) default, acceleration, repossession, foreclosure, or eviction, or the right to cure", "a primary residence of an individual;"),
         (S+"REVIEW5A_US_15USC_7002_ESIGN.txt", "(B) if enacted or adopted after June 30, 2000", "makes specific reference to this chapter.")]),
 dict(id="R5A-02", kind="gap", severity="critical", rule_ids=["NYC:CPL-20-700"],
  step="S5 charges / S13 collection conduct", universe=["U5A-114", "U5A-115", "U5A-116"],
  finding="No rule states GBL 349 at all, and in particular not as rewritten by the FAIR Business Practices Act (L.2025 c.708, signed 2025-12-19, effective the 60th day, 2026-02-17). It now bans unfair and abusive acts (not only deceptive ones) in any business, including residential leasing and collection, with no 'consumer-oriented' limit in Attorney General enforcement. A standard move-out charge practice (e.g., a fee the tenant cannot avoid or understand) is judged under the unfairness/abusiveness tests. The private action remains limited to deceptive acts (actual damages or $50, trebled up to $1,000 if willful, fees).",
  correct_rule="From 2026-02-17: (1) Any unfair act (causes or is likely to cause substantial injury not reasonably avoidable and not outweighed by benefits), abusive act (materially interferes with understanding a term, or takes unreasonable advantage of a tenant's lack of understanding, inability to protect interests, or reasonable reliance) or deceptive act in leasing or collecting from a residential tenant is unlawful; the Attorney General may enjoin, obtain restitution and penalties without showing consumer-oriented conduct, after 5 business days' certified-mail pre-suit notice. (2) A tenant injured by a consumer-oriented deceptive act or practice may sue for actual damages or $50, whichever is greater, trebled up to $1,000 for willful or knowing violations, plus attorney's fees. Charges and collection communications must be tested against both.",
  extra=[]),
 dict(id="R5A-03", kind="gap", severity="critical", rule_ids=["NY:HANDOFF-broker-config-collection-agency", "NY:CCA-1809(1)"],
  step="S9 hand-off (assignment) / S10 who may sue", universe=["U5A-127", "U5A-128"],
  finding="The hand-off configurations cover licensing and FDCPA status but not champerty. Judiciary Law 489 bars any collection business and any corporation from taking an assignment of a claim with the intent and primary purpose of suing on it; the $500,000 safe harbor needs a binding aggregate purchase price at or above that amount (Justinian, Court of Appeals 2016). An assignment of a former tenant's balance to Handoff or a collection agency so that the assignee can sue in its own name is champertous and void as a basis for suit; violators face a fine or misdemeanor.",
  correct_rule="Configuration A (owner keeps the claim; Handoff/agency collects as agent and any suit is the owner's): 489 does not apply. Configuration B (the balance is assigned or sold to Handoff, an affiliate or a collection business, and the assignee intends to sue on it): the assignment is champertous unless the assignee paid or is bound to pay an aggregate purchase price of at least $500,000 for claims against the same obligor (never met for a tenant balance); the assignee cannot maintain the action (defense of champerty) and faces a fine up to $5,000 (corporation) or misdemeanor (person). An assignment taken for collection without intent to sue, with suit left to the owner, is outside 489. CCA 1809 separately bars assignees from small claims.",
  extra=[]),
 dict(id="R5A-04", kind="gap", severity="critical", rule_ids=["NY:MDL-302-a(3)", "NY:MDL-302(1)(b)"],
  step="S10 preconditions to recovering rent (public-assistance tenant)", universe=["U5A-131"],
  finding="The rent-bar family (MDL 302, 302-a, 325) omits SSL 143-b(5): when the tenant was a public-assistance recipient, no money judgment for rent is available for any period during which a reported dangerous or hazardous violation was outstanding. This decides whether that part of a market-rate tenant's arrears can be kept from the deposit or sued for.",
  correct_rule="If the former tenant received public assistance with a shelter component during the period claimed, and the building had a violation of law relating to dangerous, hazardous or health-detrimental conditions reported to the social services department by the enforcing agency, then no money judgment for rent for any period while that violation was outstanding (until the date the condition was actually corrected, proved by the landlord) is available; that rent is not 'lawfully retained' from the deposit (GOL 7-108(1-a)(b)) and is not pursued. Rent for periods after correction, and damage claims, are unaffected; DSS may itself pay withheld rent after correction.",
  extra=[]),
 dict(id="R5A-05", kind="partial", severity="critical", rule_ids=["NY:COMMONLAW-belongings-abandonment", "NYC:ABANDONED-city-layer"],
  step="S2 whether and how the tenancy ends (retaking possession) / S5 belongings", universe=["U5A-068", "U5A-069", "U5A-174"],
  finding="The belongings rules state the abandonment standard for disposal but not the unlawful-eviction statutes that govern retaking the unit when the tenant has not clearly surrendered. RPAPL 768 and Admin. Code 26-521 make it unlawful to evict an occupant of 30+ days (or with a lease) other than by warrant, including by removing possessions, removing the door or changing the lock; each violation is a class A misdemeanor and a $1,000-$10,000 civil penalty (city and state), and RPAPL 853 gives treble damages. The NYC 'ABANDONED-city-layer' rule states there is no city law on a departing tenant's belongings, which is correct only after surrender or abandonment; before it, 26-521 applies.",
  correct_rule="Branch (a) tenant surrendered possession (returned keys or otherwise unequivocally gave up occupancy) or abandoned the unit: the landlord may re-enter and change locks; belongings follow the abandonment standard. Branch (b) no surrender or abandonment is established (occupant of 30+ days or with a lease, belongings present, keys not returned, no unequivocal relinquishment): the landlord may not change the lock, remove possessions or otherwise exclude the occupant without a warrant or court order; doing so is unlawful eviction (RPAPL 768; Admin. Code 26-521) punishable as a class A misdemeanor and by a civil penalty of $1,000-$10,000 per violation, with a duty to restore, and exposes the landlord to treble damages (RPAPL 853). Rent and the 14-day clock in branch (b) run from the actual vacatur established by surrender or by the warrant.",
  extra=[]),
 dict(id="R5A-06", kind="gap", severity="critical", rule_ids=["US:12CFR1006.14(b)(2)", "NYC:RCNY6-5-77(e)(1)"],
  step="S13 collection conduct (calls and texts)", universe=["U5A-200", "U5A-201", "U5A-202"], 
  finding="No rule states the TCPA, which binds any caller (owner, manager, Handoff, agency), not only debt collectors. Calls or texts to a former tenant's cell phone using an artificial or prerecorded voice, or an autodialer, need the called party's prior express consent; consent may be revoked by any reasonable means; each violation carries $500 statutory damages, trebled to $1,500 if willful. After Duguid an 'autodialer' must use a random or sequential number generator, so ordinary texting platforms are outside the ATDS clause, but prerecorded/artificial voice calls are covered regardless.",
  correct_rule="Before placing a collection or settlement call to a cellular number with an artificial or prerecorded voice (including ringless or prerecorded voicemail) or with equipment that generates numbers randomly or sequentially: have the tenant's prior express consent; honor a revocation made by any reasonable means within a reasonable time not exceeding ten business days, without designating an exclusive revocation channel (47 CFR 64.1200(a)(10)); otherwise liability is actual damages or $500 per call, up to $1,500 per call if willful or knowing. Live, manually placed calls and texts not sent by an ATDS are outside 227(b)(1)(A) (Duguid) but remain subject to FDCPA/Reg F and DCWP frequency limits where those apply.",
  extra=[(S+"REVIEW5A_US_47CFR_64.1200.txt", "All requests to revoke prior express consent or prior express written consent made in any reasonable manner must be honored", "not to exceed ten business days from receipt of such request."),
         (S+"REVIEW5A_US_47USC_227_TCPA.txt", "(B) an action to recover for actual monetary loss from such a violation, or to receive $500 in damages for each such violation", "whichever is greater")]),
 dict(id="R5A-07", kind="gap", severity="critical", rule_ids=["NY:ADJ-cotenants-payee", "NY:ADJ-cotenants-vacated"],
  step="S9 settling with one co-tenant", universe=["U5A-021", "U5A-022"],
  finding="The co-tenant rules decide who receives the refund but not what happens to the claim against the others when the landlord settles with or releases one co-tenant. GOL 15-104/15-105 fix the amount: a release with express reservation of rights preserves the claim against co-tenants (reduced by what was paid); a release without reservation satisfies the claim against the others to the released tenant's share.",
  correct_rule="When the landlord (or its collector) releases or settles with one of several jointly liable tenants or a guarantor: (a) if the release expressly reserves rights against the others, they stay liable for the balance less the amount paid and less the released obligor's share only to the extent 15-104 provides; (b) if it contains no express reservation, the claim against each other co-obligor is satisfied to the amount the landlord knew or had reason to know the released one was bound (as between them) to pay, or, without such knowledge, to the lesser of the released obligor's fractional share or the amount it was bound to pay. Every settlement with one co-tenant must say whether rights against the others are reserved.",
  extra=[]),
 dict(id="R5A-08", kind="gap", severity="critical", rule_ids=[],
  step="S9 partial payment tendered as full satisfaction", universe=["U5A-025", "U5A-026", "U5A-024"],
  finding="No rule addresses a former tenant's check or payment marked 'payment in full' for less than the balance. In New York, UCC 1-308 (formerly 1-207) lets the creditor accept it under an explicit reservation of rights without an accord and satisfaction (Horn Waterproofing, Court of Appeals 1985). Without the reservation, depositing a check tendered in full settlement of a disputed balance completes an accord and satisfaction and extinguishes the rest.",
  correct_rule="If a former tenant tenders less than the claimed balance on the condition that it be accepted in full satisfaction: (a) accepting it with an explicit reservation of rights ('without prejudice', 'under protest' or like words, e.g., endorsed on the check or stated in writing at acceptance) preserves the claim to the remainder (UCC 1-308; Horn Waterproofing); (b) accepting it without reservation, where the balance was disputed, discharges the remainder by accord and satisfaction. A written promise to accept a stated performance in future satisfaction is an enforceable executory accord (GOL 15-501).",
  extra=[]),
 dict(id="R5A-09", kind="gap", severity="critical", rule_ids=["NY:GOL-7-108(1-a)(b)-refundable", "NY:RPL-235-a"],
  step="S5 charges (electricity billed by the landlord)", universe=["U5A-153"],
  finding="GOL 7-108(1-a)(b) lets the landlord keep unpaid 'utility charges payable directly to the landlord under the lease'. Whether an electricity charge is lawful at all turns on the PSC's residential submetering rule, which no rule states: submetered electric service to residential units is lawful only if authorized by PSC order and consistent with 16 NYCRR Part 96.",
  correct_rule="Electricity billed by the landlord to a market-rate NYC tenant through submeters may be charged, retained from the deposit or pursued only if the building's submetering is and continues to be authorized by PSC order (where one was required) and consistent with the order and Part 96; otherwise the electricity charge is not a lawful charge and is not retained. Utility charges for services the landlord does not provide through authorized submetering (e.g., a flat 'utility fee') are fees, not lawful utility charges (see NY:ADJ-no-fee-retention).",
  extra=[]),
 dict(id="R5A-10", kind="gap", severity="critical", rule_ids=["US:11USC362(a)(6)", "US:11USC502(b)(6)-lessor-cap", "US:11USC542-refund-payee"],
  step="S15 bankruptcy (claim deadline)", universe=["U5A-223"],
  finding="The bankruptcy rules state the stay, setoff, the payee and the 502(b)(6) cap, but not the deadline to file a proof of claim. In chapter 7 and chapter 13 cases a claim is timely only within 70 days after the order for relief (with listed exceptions); a late claim is disallowed on objection in chapter 13 and subordinated in chapter 7.",
  correct_rule="If a former tenant files a voluntary chapter 7, 12 or 13 petition while a balance is owed (or its deposit is being held), the landlord's proof of claim (net of the deposit, subject to 502(b)(6) and 553) must be filed within 70 days after the order for relief or conversion (90 days in an involuntary chapter 7), subject to Rule 3002(c)'s listed exceptions. A claim not timely filed is disallowed (11 USC 502(b)(9)) except to the extent tardy filing is permitted by 726(a)(1)-(3) or the Rules; the debt is still subject to discharge.",
  extra=[(S+"REVIEW4A_US_11USC_502_uscode.txt", "(9) proof of such claim is not timely filed", "under the Federal Rules of Bankruptcy Procedure")]),
 dict(id="R5A-11", kind="gap", severity="critical", rule_ids=["NY:RPL-220", "NY:RPL-232-c"],
  step="S2 when rent stops after a summary proceeding / S9 balance", universe=["U5A-067", "U5A-259"],
  finding="No rule states what the landlord may still recover after a holdover or nonpayment judgment. RPAPL 749(3) (as amended 2019) lets the petitioner recover by separate action any sum payable when the proceeding began and the reasonable value of use and occupancy up to the warrant for periods the agreement does not cover; RPAPL 741(5) lets the petition itself seek use and occupancy only if the notice of petition demanded it.",
  correct_rule="Where a summary proceeding preceded the move-out: amounts not awarded in the judgment that were payable when the proceeding was commenced, and the reasonable value of use and occupancy to the date the warrant issued (for periods without a rent term), may be pursued by separate action; use and occupancy is recoverable in the proceeding only if the notice of petition contained the demand. After the warrant, charges accrue only as use and occupancy for any continued occupation.",
  extra=[]),
 dict(id="R5A-12", kind="gap", severity="critical", rule_ids=["NY:RPL-235-a"],
  step="S5 credits", universe=["U5A-076"],
  finding="RPL 235-a (utility offset) is stated but MDL 302-c is not: in a multiple dwelling with an oil-fired heating plant the owner fails to supply, tenants who buy oil following the statute's steps may deduct the payment from rent. The account must credit it.",
  correct_rule="If during the tenancy the owner failed to have heating oil supplied and the tenant (alone or with others) paid for delivery after substantially complying with 302-c's steps (reasonable efforts to reach the owner, etc.), the payment (allocated per the statute) is deductible from rent: credit it on the move-out account; rent claimed for those months is reduced by it.",
  extra=[]),
 dict(id="R5A-13", kind="gap", severity="critical", rule_ids=["US:24CFR100.65-terms", "NY:EXEC-296(5)(a)(2)-terms", "NYC:ADC-8-107(5)(a)-terms"],
  step="S21 anti-discrimination (who is liable)", universe=["U5A-212", "U5A-211"],
  finding="The anti-discrimination rules bind owners and agents but do not state HUD's liability rule: a person is directly liable for its own discriminatory practices and for failing to correct an agent's or employee's discrimination it knew of, and vicariously liable for its agents' and employees' discriminatory practices regardless of knowledge. 42 USC 3617 separately bars coercion, intimidation, threats or interference (e.g., collection threats because the tenant asserted fair-housing rights).",
  correct_rule="Owner and manager are each liable under the Fair Housing Act for discriminatory charges, deductions or collection conduct by their agents or employees (including Handoff or a collection agency acting for them) on a vicarious basis, and directly for their own conduct and for failing to take prompt corrective action they had the power to take; collection conduct that coerces, intimidates, threatens or interferes with a tenant because of the exercise of fair-housing rights violates 3617.",
  extra=[]),
 dict(id="R5A-14", kind="gap", severity="critical", rule_ids=["NY:GBL-899-bb-safeguards", "NYC:ADC-26-3002(c)-moveout-data"],
  step="S20 data (breach)", universe=["U5A-125"],
  finding="GBL 899-bb (safeguards) is stated but not GBL 899-aa (breach notification). Any business owning or licensing computerized private information of NY residents (tenant SSN, account or driver's licence numbers held in the tenant file, including by a manager or Handoff) must notify affected residents of a breach in the most expedient time possible and within 30 days after discovery, and notify the AG, Department of State and State Police (and DFS for covered entities).",
  correct_rule="If a tenant's private information held by the owner, manager or Handoff is, or is reasonably believed to have been, accessed or acquired without authorization: notify each affected resident within 30 days after discovery (law-enforcement delay excepted), with the content 899-aa requires, and notify the state agencies it lists (a service provider holding data for the owner notifies the owner immediately). Failure exposes the business to AG civil penalties.",
  extra=[]),
]
